    '38:69' => array('ar' => 'ما كانَ لِىَ مِن عِلمٍ بِالمَلَإِ الأَعلىٰ إِذ يَختَصِمونَ', 'en' => '"I had no knowledge previously, about the feud in the High Society.', 'ta' => 'மேலான சமூகத்தாரின் கலகத்தைப் பற்றி, இதற்கு முன்னர் நான் எந்த அறிவையும் கொண்டிருக்கவில்லை.'),
    '2:30' => array('ar' => 'وَإِذ قالَ رَبُّكَ لِلمَلٰئِكَةِ إِنّى جاعِلٌ فِى الأَرضِ خَليفَةً قالوا أَتَجعَلُ فيها مَن يُفسِدُ فيها وَيَسفِكُ الدِّماءَ وَنَحنُ نُسَبِّحُ بِحَمدِكَ وَنُقَدِّسُ لَكَ قالَ إِنّى أَعلَمُ ما لا تَعلَمونَ', 'en' => 'Recall that your Lord said to the angels, "I am placing a representative (a temporary god) on Earth." They said, "Will You place therein one who will spread evil therein and shed blood, while we sing Your praises, glorify You, and uphold Your absolute authority?" He said, "I know what you do not know."', 'ta' => 'உம்முடைய இரட்சகர் வானவர்களிடம் கூறியதை நினைவு கூர்ந்திடுங்கள், பூமியில் ஒரு பிரதிநிதியை (நிலையற்ற ஒரு தெய்வம்) நான் அமர்த்துகின்றேன் அவர்கள் கூறினர், நாங்கள் உம் புகழாரங்களைப் பாடிக் கொண்டும், உம்மைத் துதித்துக் கொண்டும், உம்முடைய ஏகோபித்த அதிகாரத்தை ஆதரித்துக் கொண்டும் இருக்கும் போது, அங்கே தீமைகளைப் பரப்பி, இரத்தம் சிந்தக் கூடிய ஒருவனையா அங்கே நீர் அமைப்பீர்? அவர் கூறினார், நீங்கள் அறியாதவற்றை நான் அறிவேன்.'),
    '36:60' => array('ar' => 'أَلَم أَعهَد إِلَيكُم يٰبَنى ءادَمَ أَن لا تَعبُدُوا الشَّيطٰنَ إِنَّهُ لَكُم عَدُوٌّ مُبينٌ', 'en' => 'Did I not covenant with you, O Children of Adam, that you shall not worship the devil? That he is your most ardent enemy?', 'ta' => 'உங்களிடம் நான் உடன்படிக்கை செய்து கொள்ளவில்லையா, ஆதமின் சந்ததிகளே, நீங்கள் சாத்தானை வழிபடக் கூடாதென்று? அவன் உங்களுடைய மிகத் தீவிரமான விரோதியென்று?'),
    '67:1' => array('ar' => 'تَبٰرَكَ الَّذى بِيَدِهِ المُلكُ وَهُوَ عَلىٰ كُلِّ شَىءٍ قَديرٌ', 'en' => 'Most exalted is the One in whose hands is all kingship, and He is Omnipotent.', 'ta' => 'அரசுரிமை அனைத்தும் எவருடைய கரங்களில் உள்ளதோ அந்த ஒருவர் மிகவும் மேன்மையானவர், மேலும் அவர் சர்வசக்தியுடையவர்.'),
    '67:2' => array('ar' => 'الَّذى خَلَقَ المَوتَ وَالحَيوٰةَ لِيَبلُوَكُم أَيُّكُم أَحسَنُ عَمَلًا وَهُوَ العَزيزُ الغَفورُ', 'en' => 'The One who created death and life for the purpose of distinguishing those among you who would do better. He is the Almighty, the Forgiving.', 'ta' => 'உங்களுக்கிடையில் சிறப்பாகச் செயல்படக் கூடியவர்கள் யார் என்பதைப் பிரித்தறியும் நோக்கத்திற்காக மரணத்தையும் வாழ்வையும் படைத்த அந்த ஒருவர். அவர்தான் எல்லாம் வல்லவர், மன்னிக்கின்றவர்.'),
    '7:172' => array('ar' => 'وَإِذ أَخَذَ رَبُّكَ مِن بَنى ءادَمَ مِن ظُهورِهِم ذُرِّيَّتَهُم وَأَشهَدَهُم عَلىٰ أَنفُسِهِم أَلَستُ بِرَبِّكُم قالوا بَلىٰ شَهِدنا أَن تَقولوا يَومَ القِيٰمَةِ إِنّا كُنّا عَن هٰذا غٰفِلينَ', 'en' => 'Recall that your Lord summoned all the descendants of Adam, and had them bear witness for themselves: "Am I not your Lord?" They all said, "Yes. We bear witness." Thus, you cannot say on the Day of Resurrection, "We were not aware of this."', 'ta' => 'ஆதமுடைய வழிவந்தவர்கள் அனைவரையும் உம் இரட்சகர் ஒன்று திரட்டி, அவர்களுக்கு அவர்களையே சாட்சியாக வைத்ததை நினைவு கூர்ந்திடுவீராக: நான்தான் உங்களுடைய இரட்சகன் அல்லவா? அவர்கள் அனைவரும் கூறினர், ஆம். நாங்கள் சாட்சி பகர்கின்றோம். ஆகவே, உயிர்த்தெழுப்பப்படுகின்ற நாள் அன்று, இது குறித்து நாங்கள் அறியாதவர்களாக இருந்தோம், என்று நீங்கள் கூற இயலாது.'),
    '15:27' => array('ar' => 'وَالجانَّ خَلَقنٰهُ مِن قَبلُ مِن نارِ السَّمومِ', 'en' => 'As for the jinns, we created them, before that, from blazing fire.', 'ta' => 'ஜின்களைப் பொறுத்தவரை, அதற்கு முன்னர், கொழுந்து விட்டெரியும் நெருப்பிலிருந்து, அவர்களை நாம் படைத்தோம்.'),
    '15:26' => array('ar' => 'وَلَقَد خَلَقنَا الإِنسٰنَ مِن صَلصٰلٍ مِن حَمَإٍ مَسنونٍ', 'en' => 'We created the human being from aged mud, like the potter\'s clay.', 'ta' => 'குயவனின் களிமண்ணைப் போன்ற, பழமையான சேற்றில் இருந்து, மனிதனை நாம் படைத்தோம்.'),
    '2:34' => array('ar' => 'وَإِذ قُلنا لِلمَلٰئِكَةِ اسجُدوا لِـٔادَمَ فَسَجَدوا إِلّا إِبليسَ أَبىٰ وَاستَكبَرَ وَكانَ مِنَ الكٰفِرينَ', 'en' => 'When we said to the angels, "Fall prostrate before Adam," they fell prostrate, except Satan; he refused, was too arrogant, and a disbeliever.', 'ta' => 'ஆதமின் முன் சிரம் பணிந்து விழுங்கள் என வானவர்களிடம் நாம் கூறிய பொழுது, அவர்கள் சிரம் பணிந்து விழுந்தனர், சாத்தானைத் தவிர; அவன் ஏற்கமறுத்தான், மிகவும் ஆணவம் கொண்டவனாகவும், நம்பமறுக்கின்ற ஒருவனாகவும் இருந்தான்.'),
    '7:11' => array('ar' => 'وَلَقَد خَلَقنٰكُم ثُمَّ صَوَّرنٰكُم ثُمَّ قُلنا لِلمَلٰئِكَةِ اسجُدوا لِـٔادَمَ فَسَجَدوا إِلّا إِبليسَ لَم يَكُن مِنَ السّٰجِدينَ', 'en' => 'We created you, then we shaped you, then we said to the angels, "Fall prostrate before Adam." They fell prostrate, except Iblees (Satan); he was not with the prostrators.', 'ta' => 'நாம் உங்களைப் படைத்தோம், பின்னர் நாம் உங்களுக்கு உருக்கொடுத்தோம், பின்னர் நாம் வானவர்களை நோக்கிக் கூறினோம், ஆதமின் முன் சிரம் பணிந்து விழுங்கள். அவர்கள் சிரம் பணிந்து வீழ்ந்தனர், இப்லீஸைத் (சாத்தான்) தவிர; சிரம் பணிந்தவர்களுடன் அவன் இருந்திடவில்லை.'),
    '17:61' => array('ar' => 'وَإِذ قُلنا لِلمَلٰئِكَةِ اسجُدوا لِـٔادَمَ فَسَجَدوا إِلّا إِبليسَ قالَ ءَأَسجُدُ لِمَن خَلَقتَ طينًا', 'en' => 'When we said to the angels, "Fall prostrate before Adam," they fell prostrate, except Satan. He said, "Shall I prostrate to one You created from mud?"', 'ta' => 'வானவர்களிடம் நாம் ஆதமின் முன் சிரம்பணியுங்கள், என்று கூறிய போது, அவர்கள் சிரம் பணிந்தனர், சாத்தானைத் தவிர. அவன் கூறினான், நீர் சேற்றால் படைத்த ஒருவருக்கு நான் சிரம்பணிய வேண்டுமா?'),
    '18:50' => array('ar' => 'وَإِذ قُلنا لِلمَلٰئِكَةِ اسجُدوا لِـٔادَمَ فَسَجَدوا إِلّا إِبليسَ كانَ مِنَ الجِنِّ فَفَسَقَ عَن أَمرِ رَبِّهِ أَفَتَتَّخِذونَهُ وَذُرِّيَّتَهُ أَولِياءَ مِن دونى وَهُم لَكُم عَدُوٌّ بِئسَ لِلظّٰلِمينَ بَدَلًا', 'en' => 'We said to the angels, "Fall prostrate before Adam." They fell prostrate, except Satan. He became a jinn, for he disobeyed the order of His Lord. Will you choose him and his descendants as lords instead of Me, even though they are your enemies? What a miserable substitute!', 'ta' => 'நாம் வானவர்களிடம் கூறினோம், ஆதமின் முன் சிரம் பணியுங்கள். அவர்கள் சிரம் பணிந்தனர், சாத்தானைத் தவிர. அவன் ஒரு ஜின்னாக ஆனான், ஏனெனில் அவனுடைய இரட்சகரின் கட்டளைக்கு அவன் கீழ்ப்படிய மறுத்தான். அவர்கள் உங்கள் விரோதிகளாக இருந்த போதிலும், எனக்குப் பதிலாக அவனையும் அவனுடைய சந்ததியினரையும் நீங்கள் எஜமானர்களாக எடுத்துக்கொள்வீர்களா? என்ன ஒரு பரிதாபகரமான மாற்று!'),
    '20:116' => array('ar' => 'وَإِذ قُلنا لِلمَلٰئِكَةِ اسجُدوا لِـٔادَمَ فَسَجَدوا إِلّا إِبليسَ أَبىٰ', 'en' => 'Recall that we said to the angels, "Fall prostrate before Adam." They fell prostrate, except Satan; he refused.', 'ta' => 'வானவர்களிடம் நாம் கூறியதை நினைவு கூர்ந்திடுங்கள், ஆதமின் முன் சிரம் பணிந்து விழுங்கள். அவர்கள் சிரம் பணிந்து விழுந்தனர், சாத்தானைத் தவிர; அவன் மறுத்து விட்டான்.'),
    '28:68' => array('ar' => 'وَرَبُّكَ يَخلُقُ ما يَشاءُ وَيَختارُ ما كانَ لَهُمُ الخِيَرَةُ سُبحٰنَ اللَّهِ وَتَعٰلىٰ عَمّا يُشرِكونَ', 'en' => 'Your Lord is the One who creates whatever He wills, and chooses; no one else does any choosing. Glory be to God, the Most Exalted. He is far above needing partners.', 'ta' => 'உம்முடைய இரட்சகர்தான் அவர் நாடிய எதனையும் படைப்பவர், மேலும் தேர்ந்தெடுப்பவர்; வேறு எவர் ஒருவரும் எதனையும் தேர்ந்தெடுப்பதில்லை. கடவுள் துதிப்பிற்குரியவர், மிகவும் உயர்ந்தவர். பங்குதாரர்கள் தேவைப்படுவதற்கும் அப்பாற்பட்டு அவர் மிகவும் மேலானவர்.'),
    '7:27' => array('ar' => 'يٰبَنى ءادَمَ لا يَفتِنَنَّكُمُ الشَّيطٰنُ كَما أَخرَجَ أَبَوَيكُم مِنَ الجَنَّةِ يَنزِعُ عَنهُما لِباسَهُما لِيُرِيَهُما سَوءٰتِهِما إِنَّهُ يَرىٰكُم هُوَ وَقَبيلُهُ مِن حَيثُ لا تَرَونَهُم إِنّا جَعَلنَا الشَّيٰطينَ أَولِياءَ لِلَّذينَ لا يُؤمِنونَ', 'en' => 'O children of Adam, do not let the devil dupe you as he did when he caused the eviction of your parents from Paradise, and the removal of their garments to expose their bodies. He and his tribe see you, while you do not see them. We appoint the devils as companions of those who do not believe.', 'ta' => 'ஆதமுடைய சந்ததியினரே, சுவனத்திலிருந்து உங்களுடைய பெற்றோர்கள் வெளியேற்றப்படவும், மேலும் அவர்களுடைய உடல்கள் வெளிப்படுத்தப்படுவதற்காக அவர்களுடைய ஆடைகள் நீக்கப்படவும் காரணமாகிய போது, அவன் செய்ததைப் போல், உங்களையும் சாத்தான் ஏய்த்து விட நீங்கள் அனுமதிக்காதீர்கள். அவனும் அவனுடைய வம்சத்தவரும் உங்களைப் பார்க்கின்றனர், அதே சமயம் நீங்களோ அவர்களைப் பார்ப்பதில்லை. நம்பிக்கை கொள்ளாதவர்களுடைய தோழர்களாக சாத்தான்களை நாம் நியமித்து விடுகின்றோம்.'),
    '50:23' => array('ar' => 'وَقالَ قَرينُهُ هٰذا ما لَدَىَّ عَتيدٌ', 'en' => 'The companion said, "Here is my formidable testimony."', 'ta' => 'அக்கூட்டாளி கூறினான், இதோ என்னுடைய வலிமையான சான்று.'),
    '4:48' => array('ar' => 'إِنَّ اللَّهَ لا يَغفِرُ أَن يُشرَكَ بِهِ وَيَغفِرُ ما دونَ ذٰلِكَ لِمَن يَشاءُ وَمَن يُشرِك بِاللَّهِ فَقَدِ افتَرىٰ إِثمًا عَظيمًا', 'en' => 'God does not forgive idolatry, but He forgives lesser offenses for whomever He wills. Anyone who sets up idols beside God, has forged a horrendous offense.', 'ta' => 'போலித் தெய்வ வழிபாட்டைக் கடவுள் மன்னிப்பதில்லை. ஆனால் தான் நாடுகின்ற எவருக்கும் அதை விடச் சிறிய பாவங்களை அவர் மன்னிக்கின்றார். கடவுளுடன் போலித் தெய்வங்களை அமைத்துக்கொள்பவர் எவராயினும், படு பயங்கரமானதொரு பாவத்தை ஜோடித்துவிட்டார்.'),
    '4:116' => array('ar' => 'إِنَّ اللَّهَ لا يَغفِرُ أَن يُشرَكَ بِهِ وَيَغفِرُ ما دونَ ذٰلِكَ لِمَن يَشاءُ وَمَن يُشرِك بِاللَّهِ فَقَد ضَلَّ ضَلٰلًا بَعيدًا', 'en' => 'God does not forgive idol worship (if maintained until death), and He forgives lesser offenses for whomever He wills. Anyone who idolizes any idol beside God has strayed far astray.', 'ta' => 'போலித்தெய்வ வழிபாட்டினை (மரணம் வரை தொடர்ந்து செய்து கொண்டிருந்தால்) கடவுள் மன்னிப்பதில்லை, ஆயினும் தான் நாடுகின்ற எவருக்கும் அதனை விடச் சிறிய குற்றங்களை அவர் மன்னிக்கின்றார். கடவுளுடன் எந்த போலித் தெய்வத்தையும் இணைத்து வழிபாடு செய்கின்ற எவரும் மிக நெடிய வழிதவறுதலில் தவறிச் சென்று விட்டார்.'),
    '36:66' => array('ar' => 'وَلَو نَشاءُ لَطَمَسنا عَلىٰ أَعيُنِهِم فَاستَبَقُوا الصِّرٰطَ فَأَنّىٰ يُبصِرونَ', 'en' => 'If we will, we can veil their eyes and, consequently, when they seek the path, they will not see.', 'ta' => 'நாம் நாடினால், அவர்களுடைய கண்களை நாம் திரையிட்டு விட முடியும், அதன் விளைவாக, அவர்கள் பாதையைத் தேடும் பொழுது, அவர்கள் பார்க்க மாட்டார்கள்.'),
    '26:89' => array('ar' => 'إِلّا مَن أَتَى اللَّهَ بِقَلبٍ سَليمٍ', 'en' => 'Only those who come to God with their whole heart (will be saved).', 'ta' => 'தங்களுடைய முழு இதயத்துடன் கடவுளிடம் வருபவர்கள் மட்டுமே (காப்பாற்றப்படுவார்கள்).'),
    '17:110' => array('ar' => 'قُلِ ادعُوا اللَّهَ أَوِ ادعُوا الرَّحمٰنَ أَيًّا ما تَدعوا فَلَهُ الأَسماءُ الحُسنىٰ وَلا تَجهَر بِصَلاتِكَ وَلا تُخافِت بِها وَابتَغِ بَينَ ذٰلِكَ سَبيلًا', 'en' => 'Say, "Call Him God, or call Him Most Gracious; whichever name you use, to Him belongs the best names." You shall not utter your Contact Prayers (Salat) too loudly, nor secretly; use a moderate tone.', 'ta' => 'கூறும், கடவுள் என அவரை அழையுங்கள், அல்லது மிக்க அருளாளர் என அவரை அழையுங்கள்; எந்த ஒரு பெயரை நீங்கள் பயன்படுத்தினாலும், அழகிய பெயர்கள்தான் அவருக்குரியவை. உமது (ஸலாத்) தொடர்புத் தொழுகைகளை நீர் மிகவும் சப்தமாகவோ, அன்றி இரகசியமாகவோ கூற வேண்டாம், நடுத்தரமானதொரு தொனியைப் பயன்படுத்துவீராக.'),
    '7:180' => array('ar' => 'وَلِلَّهِ الأَسماءُ الحُسنىٰ فَادعوهُ بِها وَذَرُوا الَّذينَ يُلحِدونَ فى أَسمٰئِهِ سَيُجزَونَ ما كانوا يَعمَلونَ', 'en' => 'To God belongs the most beautiful names; call upon Him therewith, and disregard those who distort His names. They will be requited for their sins.', 'ta' => 'மிகவும் அழகிய பெயர்கள் கடவுளுக்கே உரியன; அதனைக் கொண்டு அவரை அழையுங்கள், அவருடைய பெயர்களைத் திரிப்பவர்களை அலட்சியம் செய்திடுங்கள். அவர்களுடைய பாவங்களுக்காக அவர்கள் கூலி கொடுக்கப்படுவார்கள்.'),
    '41:44' => array('ar' => 'وَلَو جَعَلنٰهُ قُرءانًا أَعجَمِيًّا لَقالوا لَولا فُصِّلَت ءايٰتُهُ ءَأَعجَمِىٌّ وَعَرَبِىٌّ قُل هُوَ لِلَّذينَ ءامَنوا هُدًى وَشِفاءٌ وَالَّذينَ لا يُؤمِنونَ فى ءاذانِهِم وَقرٌ وَهُوَ عَلَيهِم عَمًى أُولٰئِكَ يُنادَونَ مِن مَكانٍ بَعيدٍ', 'en' => 'If we made it a non-Arabic Quran they would have said, "Why did it come down in that language?" Whether it is Arabic or non-Arabic, say, "For those who believe, it is a guide and healing. As for those who disbelieve, they will be deaf and blind to it, as if they are being addressed from faraway."', 'ta' => 'அரபி மொழி அல்லாத குர்ஆனாக நாம் இதனை ஆக்கியிருப்போமாயின், அவர்கள் கூறியிருப்பார்கள், ஏன் இது அந்த மொழியில் இறங்கி வந்தது? அது அரபி மொழியோ அல்லது அரபி மொழி அல்லாததோ, கூறுவீராக, நம்பிக்கை கொண்டவர்களுக்கு, இது ஒரு வழிகாட்டலும் நிவாரணமும் ஆகும். நம்பமறுப்பவர்களைப் பொறுத்தவரை, அவர்கள் மிகத் தொலைவிலிருந்து உரையாற்றப்படுவதைப் போன்று, இதன்பால் அவர்கள் செவிடர்களாகவும் குருடர்களாகவும் இருப்பார்கள்.'),
    '17:45' => array('ar' => 'وَإِذا قَرَأتَ القُرءانَ جَعَلنا بَينَكَ وَبَينَ الَّذينَ لا يُؤمِنونَ بِالـٔاخِرَةِ حِجابًا مَستورًا', 'en' => 'When you read the Quran, we place between you and those who do not believe in the Hereafter an invisible barrier.', 'ta' => 'நீர் குர்ஆனைப் படிக்கும் போது, உமக்கும் மறுவுலகின் மீது நம்பிக்கை கொள்ளாதோருக்கும் இடையில் காணமுடியாததொரு தடுப்பினை நாம் அமைத்து விடுகின்றோம்.'),
    '18:57' => array('ar' => 'وَمَن أَظلَمُ مِمَّن ذُكِّرَ بِـٔايٰتِ رَبِّهِ فَأَعرَضَ عَنها وَنَسِىَ ما قَدَّمَت يَداهُ إِنّا جَعَلنا عَلىٰ قُلوبِهِم أَكِنَّةً أَن يَفقَهوهُ وَفى ءاذانِهِم وَقرًا وَإِن تَدعُهُم إِلَى الهُدىٰ فَلَن يَهتَدوا إِذًا أَبَدًا', 'en' => 'Who are more evil than those who are reminded of their Lord\'s proofs, then disregard them, without realizing what they are doing. Consequently, we place shields on their hearts to prevent them from understanding it (the Quran), and deafness in their ears. Thus, no matter what you do to guide them, they can never ever be guided.', 'ta' => 'தங்கள் இரட்சகரின் சான்றுகள் குறித்து நினைவூட்டப்பட்டும் பின்னர் தாங்கள் என்ன செய்கின்றோம் என்பதை உணர்ந்து கொள்ளாது, அவற்றைப் புறக்கணிப்பவர்களை விட மிகத் தீயவர்கள் யார். அதன் விளைவாக, இதனை (இந்தக் குர்ஆனை) புரிந்து கொள்வதை விட்டும் அவர்களைத் தடுப்பதற்காக அவர்களுடைய இதயங்களின் மீது கவசங்களையும், அவர்களுடைய காதுகளில் செவிட்டுத்தனத்தையும் நாம் அமைத்து விடுகின்றோம். எனவே, அவர்களை வழிநடத்துவதற்காக நீர் என்ன செய்கின்றீர் என்பது பொருட்டல்ல, அவர்கள் ஒருபோதும் எக்காலத்திலும் வழிநடத்தப்படமாட்டார்கள்.'),
    '56:79' => array('ar' => 'لا يَمَسُّهُ إِلَّا المُطَهَّرونَ', 'en' => 'None can grasp it except the sincere.', 'ta' => 'உண்மையானவர்களைத் தவிர எவரும் அதனைக் கிரகிக்க இயலாது.'),
    '2:228' => array('ar' => 'وَالمُطَلَّقٰتُ يَتَرَبَّصنَ بِأَنفُسِهِنَّ ثَلٰثَةَ قُروءٍ وَلا يَحِلُّ لَهُنَّ أَن يَكتُمنَ ما خَلَقَ اللَّهُ فى أَرحامِهِنَّ إِن كُنَّ يُؤمِنَّ بِاللَّهِ وَاليَومِ الـٔاخِرِ وَبُعولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فى ذٰلِكَ إِن أَرادوا إِصلٰحًا وَلَهُنَّ مِثلُ الَّذى عَلَيهِنَّ بِالمَعروفِ وَلِلرِّجالِ عَلَيهِنَّ دَرَجَةٌ وَاللَّهُ عَزيزٌ حَكيمٌ', 'en' => 'The divorced women shall wait three menstruations (before marrying another man). It is not lawful for them to conceal what God creates in their wombs, if they believe in God and the Last Day. (In case of pregnancy,) the husband\'s wishes shall supersede the wife\'s wishes, if he wants to remarry her. The women have rights, as well as obligations, equitably. Thus, the man\'s wishes prevail (in case of pregnancy). God is Almighty, Most Wise.', 'ta' => 'விவாகரத்துச் செய்யப்பட்டு விட்ட பெண்கள் (மற்றொரு ஆணை மணம் புரிவதற்கு முன்) மூன்று மாதவிடாய்கள் காத்திருக்க வேண்டும். அவர்கள் கடவுள் மற்றும் இறுதி நாளின் மீது நம்பிக்கை கொண்டவர்களாக இருந்தால், அவர்களுடைய கருப்பைகளில் கடவுள் படைக்கின்றவற்றை மறைப்பது அவர்களுக்கு அனுமதிக்கப்பட்டதல்ல. (கர்ப்பம் தரித்திருக்குமாயின்), அவன் அவளை மீண்டும் மணம் செய்து கொள்ள விரும்பினால், கணவனின் விருப்பங்களின்படி மனைவியின் விருப்பங்கள் மாற்றியமைத்துக்கொள்ளப்பட வேண்டும். பெண்களுக்கு உரிமைகளும், அவ்வண்ணமே கடமைகளும், நீதமாக உண்டு. எனவே, (கர்ப்பம் தரித்திருக்குமாயின்) ஆணின் விருப்பங்களே மிகைத்து நிற்கும். கடவுள் எல்லாம் வல்லவர், ஞானம் மிகுந்தவர்.'),
    '28:23' => array('ar' => 'وَلَمّا وَرَدَ ماءَ مَديَنَ وَجَدَ عَلَيهِ أُمَّةً مِنَ النّاسِ يَسقونَ وَوَجَدَ مِن دونِهِمُ امرَأَتَينِ تَذودانِ قالَ ما خَطبُكُما قالَتا لا نَسقى حَتّىٰ يُصدِرَ الرِّعاءُ وَأَبونا شَيخٌ كَبيرٌ', 'en' => 'When he reached Midyan\'s water, he found a crowd of people watering, and noticed two women waiting on the side. He said, "What is it that you need?" They said, "We are not able to water, until the crowd disperses, and our father is an old man."', 'ta' => 'மித்யனின் நீர்நிலையை அவர் அடைந்தபோது, மக்களில் ஒரு கூட்டத்தினர் தண்ணீர் எடுத்துக் கொண்டிருப்பதை அவர் கண்டார், மேலும் ஓரத்தில் இரு பெண்கள் காத்துக் கொண்டிருப்பதையும் அவர் கவனித்தார். அவர் கூறினார், உங்களுக்கு வேண்டியதென்ன? அவர்கள் கூறினர், கூட்டம் கலைந்து செல்லும் வரை, எங்களால் தண்ணீர் எடுத்துக்கொள்ள முடியவில்லை, மேலும் எங்கள் தந்தையோ வயது முதிர்ந்த ஒருவராக இருக்கின்றார்.'),
    '3:19' => array('ar' => 'إِنَّ الدّينَ عِندَ اللَّهِ الإِسلٰمُ وَمَا اختَلَفَ الَّذينَ أوتُوا الكِتٰبَ إِلّا مِن بَعدِ ما جاءَهُمُ العِلمُ بَغيًا بَينَهُم وَمَن يَكفُر بِـٔايٰتِ اللَّهِ فَإِنَّ اللَّهَ سَريعُ الحِسابِ', 'en' => 'The only religion approved by God is "Submission." Ironically, those who have received the scripture are the ones who dispute this fact, despite the knowledge they have received, due to jealousy. For such rejectors of God\'s revelations, God is most strict in reckoning.', 'ta' => 'கடவுளால் அங்கீகரிக்கப்பட்ட ஒரே மார்க்கம் சரணடைதல் ஆகும். முரண் நகையாக, வேதத்தைப் பெற்றவர்கள்தான் அவர்கள் பெற்றிருக்கின்ற அறிவிற்குப் பின்னரும், பொறாமையின் காரணமாக, இந்த உண்மையைத் தர்க்கிப்பவர்களாக இருக்கின்றனர். கடவுளின் வெளிப்பாடுகளை ஏற்கமறுக்கின்ற இத்தகையவர்களுக்கு, கணக்கெடுப்பதில் கடவுள் மிகவும் கண்டிப்பானவராக இருக்கின்றார்.'),
);


// Build the FAQPage JSON-LD schema from the same data (single source of truth).
$ga_faq_schema = array(
    '@context'   => 'https://schema.org',
    '@type'      => 'FAQPage',
    'mainEntity' => array(),
);
foreach ($ga_faq as $ga_cat) {
    foreach ($ga_cat['items'] as $ga_item) {
        $ga_q = strtr($ga_item['q'], $ga_faq_urls);
        $ga_a = strtr($ga_item['a'], $ga_faq_urls);
        $ga_faq_schema['mainEntity'][] = array(
            '@type'          => 'Question',
            'name'           => wp_strip_all_tags(html_entity_decode($ga_q, ENT_QUOTES)),
            'acceptedAnswer' => array(
                '@type' => 'Answer',
                'text'  => wp_strip_all_tags(html_entity_decode($ga_a, ENT_QUOTES)),
            ),
        );
    }
}

get_header();
?>
<style>
.faq-search-wrap{max-width:560px;margin:0 auto 34px;position:relative}
.faq-search{width:100%;padding:15px 20px 15px 48px;border-radius:999px;border:1px solid var(--line-2);
  background:var(--panel-2);color:var(--ink);font-size:15.5px;font-family:var(--font-body)}
.faq-search:focus{outline:none;border-color:var(--gold)}
.faq-search-ic{position:absolute;left:18px;top:50%;transform:translateY(-50%);opacity:.55;pointer-events:none}
.faq-pills{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin:0 0 8px}
.faq-pill{padding:9px 18px;border-radius:999px;border:1px solid var(--line);color:var(--muted);
  font-size:14px;font-weight:600;text-decoration:none;transition:.2s}
.faq-pill:hover{color:var(--gold-bright);border-color:var(--gold)}
.faq-list{max-width:820px;margin:0 auto}
.faq-item{background:linear-gradient(180deg,var(--panel),var(--panel-2));border:1px solid var(--line-2);
  border-radius:var(--radius);margin-bottom:14px;overflow:hidden;transition:border-color .2s,box-shadow .2s}
.faq-item.open{border-color:var(--gold);box-shadow:var(--shadow-sm)}
.faq-q{width:100%;display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:20px 24px;background:none;border:0;cursor:pointer;text-align:left;
  font-family:var(--font-body);font-size:16.5px;font-weight:700;color:var(--ink)}
.faq-chev{flex:none;color:var(--gold-bright);font-size:14px;transition:transform .25s}
.faq-item.open .faq-chev{transform:rotate(180deg)}
.faq-a{max-height:0;overflow:hidden;transition:max-height .32s ease}
.faq-a-in{padding:0 24px 20px}
.faq-a-in p{color:var(--muted);line-height:1.75;font-size:15.5px;margin:0}
.faq-a-in a{color:var(--gold-bright);font-weight:600}
.faq-inline-btn{display:inline-block;margin-top:12px;padding:9px 18px;border-radius:999px;
  background:var(--gold-grad);color:#15100a;font-weight:700;font-size:14px;text-decoration:none}
.faq-empty{text-align:center;color:var(--muted);padding:40px 0;display:none}
.faq-cat{scroll-margin-top:90px}
.faq-a-in .faq-list-num{margin:10px 0 16px;padding-left:22px;color:var(--muted);line-height:1.75;font-size:15.5px}
.faq-a-in .faq-list-num li{margin-bottom:6px}
.faq-a-in h4.faq-sub{margin:20px 0 4px;color:var(--gold-bright);font-family:var(--font-display);font-size:16px;letter-spacing:.02em}
