<script type="application/ld+json"><?php echo wp_json_encode($ga_faq_schema, JSON_UNESCAPED_SLASHES); ?></script>

<script>
var GA_VERSES = <?php echo wp_json_encode($ga_faq_verses, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); ?>;
(function(){
  var items = document.querySelectorAll('.faq-item');
  items.forEach(function(item){
    var btn = item.querySelector('.faq-q');
    var panel = item.querySelector('.faq-a');
    btn.addEventListener('click', function(){
      var open = item.classList.contains('open');
      if (open) {
        item.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
        panel.style.maxHeight = '0px';
      } else {
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        panel.style.maxHeight = panel.scrollHeight + 'px';
      }
    });
  });
  window.addEventListener('resize', function(){
    document.querySelectorAll('.faq-item.open .faq-a').forEach(function(p){
      p.style.maxHeight = p.scrollHeight + 'px';
    });
  });

  var search = document.getElementById('faqSearch');
  var empty = document.getElementById('faqEmpty');
  var cats = document.querySelectorAll('.faq-cat');
  if (search) {
    search.addEventListener('input', function(){
      var q = search.value.trim().toLowerCase();
      var anyVisible = false;
      cats.forEach(function(cat){
        var catHasMatch = false;
        cat.querySelectorAll('.faq-item').forEach(function(item){
          var text = item.textContent.toLowerCase();
          var match = !q || text.indexOf(q) !== -1;
          item.style.display = match ? '' : 'none';
          if (match) catHasMatch = true;
        });
        cat.style.display = catHasMatch ? '' : 'none';
        if (catHasMatch) anyVisible = true;
      });
      empty.style.display = anyVisible ? 'none' : 'block';
    });
  }

  var vpOverlay = document.getElementById('versePopupOverlay');
  var vpBody = document.getElementById('versePopupBody');
  var vpClose = document.getElementById('versePopupClose');

  function escapeHtml(s){
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function openVersePopup(refs){
    if (!vpOverlay || !vpBody) return;
    var list = refs.split(',');
    var html = '';
    list.forEach(function(ref){
      ref = ref.trim();
      var v = GA_VERSES[ref];
      if (!v) return;
      html += '<div class="vp-block">'
        + '<span class="vp-chip">' + escapeHtml(ref) + '</span>'
        + '<div class="vp-ar">' + v.ar + '</div>'
        + '<p class="vp-en">' + v.en + '</p>'
        + '<p class="vp-ta">' + v.ta + '</p>'
        + '</div>';
    });
    if (!html) return;
    vpBody.innerHTML = html;
    vpOverlay.classList.add('open');
    vpOverlay.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeVersePopup(){
    if (!vpOverlay) return;
    vpOverlay.classList.remove('open');
    vpOverlay.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
  }

  document.addEventListener('click', function(e){
    var t = e.target.closest ? e.target.closest('.vref, .vref-cite') : null;
    if (t) {
      e.preventDefault();
      e.stopPropagation();
      var v = t.getAttribute('data-v');
      if (v) openVersePopup(v);
      return;
    }
    if (vpClose && e.target === vpClose) { closeVersePopup(); return; }
    if (vpOverlay && e.target === vpOverlay) { closeVersePopup(); return; }
  });

  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape' && vpOverlay && vpOverlay.classList.contains('open')) closeVersePopup();
  });
})();
</script>

<?php get_footer(); ?>
